build.VisitAllChildren<Task>(task => {
    if (task.Name == "Csc") {
        var project = task.GetNearestParent<Project>();
        Console.WriteLine($"\nProject: {project?.Name}");
        // Print references from task children
        foreach (var child in task.Children) {
            var str = child.ToString();
            if (str != null && (str.Contains("Newtonsoft") || str.Contains("Reference") || str.Contains("/r:")))
            {
                Console.WriteLine($"  {str}");
            }
        }
    }
});

// Look for MSBuild errors (dependency failures)
Console.WriteLine("\n=== MSBUILD ERRORS/MESSAGES about dependencies ===");
build.VisitAllChildren<Message>(msg => {
    if (msg.Text != null && (msg.Text.Contains("dependency") || msg.Text.Contains("failed") || msg.Text.Contains("not build")))
        Console.WriteLine($"  {msg.Text}");
});
EOF
